mitigation.rag:
A new security feature scans for sensitive keywords in request data to prevent JavaScript prototype pollution. If such a keyword is found, the request is rejected with HTTP response code `400` and Parse Error `105` (`INVALID_KEY_NAME`). By default, these keywords are: `{_bsontype: "Code"}`, `constructor`, `__proto__`. Users can override the default keywords by setting the new Parse Server option `requestKeywordDenylist` to `[]` and specify their own keywords as needed.

A workaround involves patching the MongoDB Node.js driver to disable BSON code execution. To apply the patch, add the following code to be executed before starting Parse Server, for example in `index.js`:

```javascript
const BSON = require('bson');
const internalDeserialize = BSON.prototype.deserialize;
BSON.prototype.deserialize = (buffer, options = Object.create(null), ...others) => {
  if (options.constructor) {
    options = Object.assign(Object.create(null), options);
  }
  return internalDeserialize(buffer, options, ...others);
};
const internalDeserializeStream = BSON.prototype.deserializeStream;
BSON.prototype.deserializeStream = (
  data,
  startIndex,
  numberOfDocuments,
  documents,
  docStartIndex,
  options = Object.create(null),
  ...others
) => {
  if (options.constructor) {
    options = Object.assign(Object.create(null), options);
  }
  return internalDeserializeStream(
    data,
    startIndex,
    numberOfDocuments,
    documents,
    docStartIndex,
    options,
    ...others
  );
};
