int file_attr_to_st_mode (DWORD attr, DWORD tag)
{
	int fMode = S_IREAD;
	if ((attr & FILE_ATTRIBUTE_REPARSE_POINT) && tag == IO_REPARSE_TAG_SYMLINK)
